// LC 8。只认 '0'..'9'；符号只允许出现在数字之前，且只有一个。
// 溢出判断放在 res = res * 10 + d 之前，正数钳到 Integer.MAX_VALUE，负数钳到 Integer.MIN_VALUE。
// 换题：纯数字串（无空格、无符号）删掉空格和符号两段；版本号不要整段调用本方法，按 '.' 分段后逐段转整数再比较，缺段当 0。
static int myAtoi(String s) {
    int n = s.length();
    int i = 0;
    while (i < n && s.charAt(i) == ' ') {
        i++;
    }
    if (i == n) {
        return 0;
    }
    int sign = 1;
    if (s.charAt(i) == '+' || s.charAt(i) == '-') {
        if (s.charAt(i) == '-') {
            sign = -1;
        }
        i++;
    }
    int res = 0;
    while (i < n && s.charAt(i) >= '0' && s.charAt(i) <= '9') {
        int d = s.charAt(i) - '0';
        if (res > (Integer.MAX_VALUE - d) / 10) {
            return sign == 1 ? Integer.MAX_VALUE : Integer.MIN_VALUE;
        }
        res = res * 10 + d;
        i++;
    }
    return sign * res;
}

