import java.util.*;

class Solution {
    public String addStrings(String num1, String num2) {
        int i = num1.length() - 1;
        int j = num2.length() - 1;
        int carry = 0; // 保存上一位产生的进位。
        StringBuilder reversed = new StringBuilder();

        // 还有未处理的位，或最后仍有进位，都必须再算一位。
        while (i >= 0 || j >= 0 || carry != 0) {
            int digit1 = i >= 0 ? num1.charAt(i) - '0' : 0;
            int digit2 = j >= 0 ? num2.charAt(j) - '0' : 0;

            int sum = digit1 + digit2 + carry;
            reversed.append(sum % 10); // 当前位只保留个位。
            carry = sum / 10;          // 十位留给下一轮当进位。

            i--;
            j--;
        }

        // 结果从低位写到高位，反转后才是正常十进制。
        return reversed.reverse().toString();
    }
}

import java.util.*;

class Solution {
    public String multiply(String num1, String num2) {
        if (num1.equals("0") || num2.equals("0")) {
            return "0";
        }

        int m = num1.length();
        int n = num2.length();
        int[] digits = new int[m + n];

        // 从低位向高位累加每一对数字的乘积，对应竖式的某一位。
        for (int i = m - 1; i >= 0; i--) {
            int a = num1.charAt(i) - '0';
            for (int j = n - 1; j >= 0; j--) {
                int b = num2.charAt(j) - '0';

                int low = i + j + 1; // 当前乘积落在的低位。
                int high = i + j;    // 进位要加到的高一位。
                int sum = a * b + digits[low];

                digits[low] = sum % 10;
                digits[high] += sum / 10;
            }
        }

        StringBuilder answer = new StringBuilder();
        int index = 0;
        // 最高位可能因长度留空而为 0，跳过它们才不会多出前导零。
        while (index < digits.length && digits[index] == 0) {
            index++;
        }
        while (index < digits.length) {
            answer.append(digits[index++]);
        }

        return answer.length() == 0 ? "0" : answer.toString();
    }
}

// LC8 原题：s 非 null，长度0..200，字符限英文字母、ASCII 数字0-9、空格 U+0020、加号、减号和小数点。数字阶段只识别0-9；遇到其他字符即停止，无数字返回0，越界裁剪到 int 边界。完整消费且出错抛异常的严格解析是下方另一接口。
import java.util.*;

class Solution {
    public int myAtoi(String s) {
        int index = 0;
        int n = s.length();

        // 前导空格不属于数值，先跳过。
        while (index < n && s.charAt(index) == ' ') {
            index++;
        }

        // 符号最多读一个，决定最终结果的正负。
        int sign = 1;
        if (index < n && (s.charAt(index) == '+' || s.charAt(index) == '-')) {
            sign = s.charAt(index) == '-' ? -1 : 1;
            index++;
        }

        long result = 0;
        // 负数绝对值上限是 2147483648，比正数多 1。
        long limit = sign == 1 ? Integer.MAX_VALUE : -(long) Integer.MIN_VALUE;

        // 遇到第一个非数字就停止，只累计连续数字。
        while (index < n && s.charAt(index) >= '0' && s.charAt(index) <= '9') {
            int digit = s.charAt(index) - '0';

            // 乘 10 之前先判断，避免 result 自己先溢出。
            if (result > (limit - digit) / 10) {
                return sign == 1 ? Integer.MAX_VALUE : Integer.MIN_VALUE;
            }

            result = result * 10 + digit;
            index++;
        }

        return (int) (sign * result);
    }
}

// 本段仅是基本累加演示：s 非 null，语法为 -?[0-9]+，至少一位 ASCII 数字，无正号、空白或其他字符，数值的绝对值≤2147483647，因而每一步正幅度累加都在 int 内。空串、单独负号和越界均不在调用域内，此演示不逐项校验。需要完整32位范围（包括−2147483648）、可选正号及明确拒绝行为时，使用题目8「字符串转换整数」补充中的 SSAIntParser.parse 严格接口。
class Solution {
    public int parseInt(String s) {
        int sign = 1;
        int index = 0;
        // 负号只看首位，数字从下一位开始累加
        if (s.charAt(0) == '-') {
            sign = -1;
            index++;
        }
        int ans = 0;
        while (index < s.length()) {
            char c = s.charAt(index++);
            // 非数字无法按十进制累加，直接拒绝
            if (c < '0' || c > '9') {
                throw new IllegalArgumentException("invalid number");
            }
            // 先乘 10 腾出个位，再加当前数位
            ans = ans * 10 + (c - '0');
        }
        return ans * sign;
    }
}

class Solution {
    public String multiply(String num1, String num2) {
        // 乘数为 0 时积就是 0，避免做出一串前导零
        if ("0".equals(num1) || "0".equals(num2)) {
            return "0";
        }

        int m = num1.length();
        int n = num2.length();
        // 两数相乘最多 m+n 位
        int[] ans = new int[m + n];

        for (int i = m - 1; i >= 0; i--) {
            for (int j = n - 1; j >= 0; j--) {
                int mul = (num1.charAt(i) - '0') * (num2.charAt(j) - '0');
                // i、j 的个位落在下标 i+j+1，进位落到 i+j
                int sum = mul + ans[i + j + 1];
                ans[i + j + 1] = sum % 10;
                ans[i + j] += sum / 10;
            }
        }

        StringBuilder sb = new StringBuilder();
        int index = 0;
        // 最高几位可能仍是 0，从第一个非零位开始输出
        while (index < ans.length && ans[index] == 0) {
            index++;
        }
        while (index < ans.length) {
            sb.append(ans[index++]);
        }
        return sb.length() == 0 ? "0" : sb.toString();
    }
}

import java.util.*;

class Solution {
    public String reverseWords(String s) {
        StringBuilder answer = new StringBuilder();
        int i = s.length() - 1;

        while (i >= 0) {
            // 从右端丢掉空格，下一个字符才是某个单词的结尾。
            while (i >= 0 && s.charAt(i) == ' ') {
                i--;
            }
            if (i < 0) {
                break;
            }

            int end = i;
            while (i >= 0 && s.charAt(i) != ' ') {
                i--;
            }
            int start = i + 1;

            // 先遇到靠后的单词，按此顺序追加即得到逆序。
            if (answer.length() > 0) {
                answer.append(' ');
            }
            answer.append(s, start, end + 1);
        }

        return answer.toString();
    }
}

// LC165 原题：两个版本号均非 null，长度各为1..500，是只含 ASCII 数字和点号的合法版本号；每一段非空，忽略前导零后的段值均在0..2147483647内。因此当前 long 逐位累加安全；不承诺比较任意长的非零数值段。
import java.util.*;

class Solution {
    public int compareVersion(String version1, String version2) {
        int i = 0;
        int j = 0;

        while (i < version1.length() || j < version2.length()) {
            long current1 = 0;
            long current2 = 0;

            // 按十进制累加，前导零被吸收；该侧已结束则这段保持 0。
            while (i < version1.length() && version1.charAt(i) != '.') {
                current1 = current1 * 10 + (version1.charAt(i) - '0');
                i++;
            }

            while (j < version2.length() && version2.charAt(j) != '.') {
                current2 = current2 * 10 + (version2.charAt(j) - '0');
                j++;
            }

            if (current1 < current2) {
                return -1;
            }
            if (current1 > current2) {
                return 1;
            }

            // 两段相等才越过点号；已到末尾时加 1 只是停在界外。
            i++;
            j++;
        }

        return 0;
    }
}

class Solution {
    public long ipToLong(String ip) {
        String[] parts = ip.split("\\.", -1);
        if (parts.length != 4) {
            throw new IllegalArgumentException("invalid ip");
        }

        // long 避免结果超过 Integer.MAX_VALUE 时变成负数
        long ans = 0;
        for (String part : parts) {
            int value = Integer.parseInt(part);
            if (value < 0 || value > 255) {
                throw new IllegalArgumentException("invalid ip segment");
            }
            // 左移 8 位腾出低字节，再并上当前段
            ans = (ans << 8) | value;
        }
        return ans;
    }
}

class Solution {
    public int strStr(String haystack, String needle) {
        if (needle.isEmpty()) {
            return 0;
        }

        int[] lps = buildLps(needle);
        int i = 0;
        int j = 0;

        while (i < haystack.length()) {
            if (haystack.charAt(i) == needle.charAt(j)) {
                i++;
                j++;
                // j 走完说明从 i - j 开始整段匹配
                if (j == needle.length()) {
                    return i - j;
                }
            } else if (j > 0) {
                // 用已匹配前后缀把模式串前滑，主串不回退
                j = lps[j - 1];
            } else {
                i++;
            }
        }

        return -1;
    }

    private int[] buildLps(String pattern) {
        int[] lps = new int[pattern.length()];
        int len = 0;
        int i = 1;

        while (i < pattern.length()) {
            if (pattern.charAt(i) == pattern.charAt(len)) {
                len++;
                lps[i] = len;
                i++;
            } else if (len > 0) {
                // 缩短到上一个前后缀，继续比当前位置
                len = lps[len - 1];
            } else {
                lps[i] = 0;
                i++;
            }
        }

        return lps;
    }
}

import java.util.*;

class Solution {
    public void rotate(int[] nums, int k) {
        int n = nums.length;
        if (n == 0) return;
        k %= n; // 转满 n 次与不转相同。

        // 整体翻转后末尾 k 个到了前面且反序，再分别翻正两段。
        reverse(nums, 0, n - 1);
        reverse(nums, 0, k - 1);
        reverse(nums, k, n - 1);
    }

    private void reverse(int[] nums, int left, int right) {
        while (left < right) {
            int temp = nums[left];
            nums[left++] = nums[right];
            nums[right--] = temp;
        }
    }
}

import java.util.*; // Java 常用集合、队列、堆与数组工具

class Solution {
    public void nextPermutation(int[] nums) {
        int i = nums.length - 2;

        // 最右的升序转折点才是还能变大的位置，右侧必为非递增。
        while (i >= 0 && nums[i] >= nums[i + 1]) i--;

        if (i >= 0) {
            // 右侧非递增，从右端遇到的第一个更大值就是刚好更大的替换。
            int j = nums.length - 1;
            while (nums[j] <= nums[i]) j--;
            swap(nums, i, j);
        }

        // 后缀翻成升序，得到当前前缀下最小的下一个排列。
        reverse(nums, i + 1, nums.length - 1);
    }

    private void reverse(int[] nums, int left, int right) {
        while (left < right) {
            swap(nums, left++, right--);
        }
    }

    private void swap(int[] nums, int i, int j) {
        int temp = nums[i];
        nums[i] = nums[j];
        nums[j] = temp;
    }
}

import java.util.*;

class Solution {
    public int firstMissingPositive(int[] nums) {
        int n = nums.length;

        for (int i = 0; i < n; i++) {
            // 只有 1..n 有位置 x-1；目标处已是该值则停止，避免来回交换。
            while (nums[i] >= 1 && nums[i] <= n
                    && nums[nums[i] - 1] != nums[i]) {
                int targetIndex = nums[i] - 1;
                int temp = nums[i];
                nums[i] = nums[targetIndex];
                nums[targetIndex] = temp;
            }
        }

        // 归位后，第一个不是 i+1 的位置就是缺失值。
        for (int i = 0; i < n; i++) {
            if (nums[i] != i + 1) return i + 1;
        }

        return n + 1;
    }
}

import java.util.*;

class Solution {
    public List<Integer> findDuplicates(int[] nums) {
        List<Integer> answer = new ArrayList<>();

        for (int i = 0; i < nums.length; i++) {
            // 前面的标记可能已把该格改成负数，取绝对值才是原来的数值。
            int value = Math.abs(nums[i]);
            int index = value - 1;

            if (nums[index] < 0) {
                // 映射位置已是负，说明 value 第二次出现。
                answer.add(value);
            } else {
                // 第一次见到：取负留下标记，下次再见到同一下标即可识别。
                nums[index] = -nums[index];
            }
        }

        return answer;
    }
}

import java.util.*;

class Solution {
    public List<Integer> findQualifiedElements(int[] nums) {
        List<Integer> answer = new ArrayList<>();
        int n = nums.length;
        if (n < 3) return answer;

        // 右侧最小值先算好，后面判断“右边都更大”才是 O(1)。
        int[] suffixMin = new int[n];
        suffixMin[n - 1] = nums[n - 1];
        for (int i = n - 2; i >= 0; i--) {
            suffixMin[i] = Math.min(nums[i], suffixMin[i + 1]);
        }

        // leftMax 只能含 i 左侧，所以要在比较之后再更新。
        int leftMax = nums[0];
        for (int i = 1; i < n - 1; i++) {
            if (leftMax < nums[i] && nums[i] < suffixMin[i + 1]) {
                answer.add(nums[i]);
            }
            leftMax = Math.max(leftMax, nums[i]);
        }
        return answer;
    }
}

// LC73 原题：matrix 非 null，为非空规则矩形，各行非 null 且等长，1≤行数、列数≤200，格值可为任意 int。主实现直接读取首行首列，零行、零列、锯齿和 null 不在调用域内；原地置零会修改输入。
import java.util.*; // 最后用 Arrays.fill 把需要清零的首行一次写完

class Solution {
    public void setZeroes(int[][] matrix) {
        int rows = matrix.length;
        int cols = matrix[0].length;

        // 首行首列马上要当标记用，先记住它们原本是否含 0
        boolean firstRowZero = false;
        boolean firstColZero = false;

        for (int c = 0; c < cols; c++) {
            if (matrix[0][c] == 0) firstRowZero = true;
        }
        for (int r = 0; r < rows; r++) {
            if (matrix[r][0] == 0) firstColZero = true;
        }

        // 内部的 0 只写进行首、列首，不必另开标记数组
        for (int r = 1; r < rows; r++) {
            for (int c = 1; c < cols; c++) {
                if (matrix[r][c] == 0) {
                    matrix[r][0] = 0;
                    matrix[0][c] = 0;
                }
            }
        }

        // 行首或列首为 0，说明这一行或这一列整段都要清
        for (int r = 1; r < rows; r++) {
            for (int c = 1; c < cols; c++) {
                if (matrix[r][0] == 0 || matrix[0][c] == 0) {
                    matrix[r][c] = 0;
                }
            }
        }

        if (firstRowZero) Arrays.fill(matrix[0], 0);
        if (firstColZero) {
            for (int r = 0; r < rows; r++) matrix[r][0] = 0;
        }
    }
}

// LC54 原题：matrix 非 null，为非空规则矩形，各行非 null 且等长，1≤行数、列数≤10，格值在−100..100。主入口沿用非空前提；补充中支持零行、零列并做形状校验的接口有独立合同。
import java.util.*; // 用 ArrayList 按访问顺序收集元素

class Solution {
    public List<Integer> spiralOrder(int[][] matrix) {
        List<Integer> answer = new ArrayList<>();
        int top = 0, bottom = matrix.length - 1;
        int left = 0, right = matrix[0].length - 1;

        while (top <= bottom && left <= right) {
            // 上边走完立刻 top++，下一层不再碰到这一行
            for (int c = left; c <= right; c++) answer.add(matrix[top][c]);
            top++;

            // 右边走完立刻 right--，已输出的列退出边界
            for (int r = top; r <= bottom; r++) answer.add(matrix[r][right]);
            right--;

            // 只剩一行时 top 已超过 bottom，不能再从右往左回头
            if (top <= bottom) {
                for (int c = right; c >= left; c--) answer.add(matrix[bottom][c]);
                bottom--;
            }

            // 只剩一列时 right 已小于 left，不能再从下往上回头
            if (left <= right) {
                for (int r = bottom; r >= top; r--) answer.add(matrix[r][left]);
                left++;
            }
        }
        return answer;
    }
}

import java.util.*; // 旋转只做原地交换，集合工具不参与计算

class Solution {
    public void rotate(int[][] matrix) {
        int n = matrix.length;

        // c 从 r+1 起交换，主对角线两侧只对调一次
        for (int r = 0; r < n; r++) {
            for (int c = r + 1; c < n; c++) {
                int temp = matrix[r][c];
                matrix[r][c] = matrix[c][r];
                matrix[c][r] = temp;
            }
        }

        // 转置后左右对换，列下标从 c 变成 n-1-c
        for (int r = 0; r < n; r++) {
            int left = 0, right = n - 1;
            while (left < right) {
                int temp = matrix[r][left];
                matrix[r][left++] = matrix[r][right];
                matrix[r][right--] = temp;
            }
        }
    }
}

// LC240 原题：matrix 非 null，为非空规则矩形，各行非 null 且等长，1≤行数、列数≤300；格值与 target 在−1000000000..1000000000，每行、每列按非递减顺序排列。主入口不检查空矩阵或形状。
import java.util.*; // 搜索只用两个下标，不借助额外容器

class Solution {
    public boolean searchMatrix(int[][] matrix, int target) {
        int row = 0;
        int col = matrix[0].length - 1;

        // 右上角左边更小、下边更大，每次可以丢掉一行或一列
        while (row < matrix.length && col >= 0) {
            int value = matrix[row][col];
            if (value == target) return true;

            if (value > target) {
                col--; // 当前列下方只会更大，剩余部分不可能等于 target
            } else {
                row++; // 当前行左侧只会更小，剩余部分不可能等于 target
            }
        }
        return false;
    }
}

class Solution {
    public int[] findDiagonalOrder(int[][] mat) {
        if (mat == null || mat.length == 0 || mat[0].length == 0) {
            return new int[0];
        }

        int rows = mat.length;
        int cols = mat[0].length;
        int[] answer = new int[rows * cols];
        int index = 0;

        // d 相同的格子在同一条副对角线上，一共 rows+cols-1 条
        for (int d = 0; d < rows + cols - 1; d++) {
            if ((d & 1) == 0) {
                // 偶数条从靠下的一端出发，才能一路向右上
                int row = Math.min(d, rows - 1);
                int col = d - row;

                while (row >= 0 && col < cols) {
                    answer[index++] = mat[row][col];
                    row--;
                    col++;
                }
            } else {
                // 奇数条从靠右的一端出发，才能一路向左下
                int col = Math.min(d, cols - 1);
                int row = d - col;

                while (col >= 0 && row < rows) {
                    answer[index++] = mat[row][col];
                    row++;
                    col--;
                }
            }
        }

        return answer;
    }
}
